<?php

declare(strict_types=1);namespace Inilim\Tool\Method\Other;

function requestHeaders_m2(?array $_server=null):array{$_server ??= $_SERVER;$headers=[];foreach($_server as $key=>$value){if(\stripos($key,'HTTP_')===0){$headers[\substr($key,5)]=$value;}elseif(\in_array($key,['CONTENT_TYPE','CONTENT_LENGTH','CONTENT_MD5'],true)&&''!==$value){$headers[$key]=$value;}}if(isset($_server['PHP_AUTH_USER'])){$headers['PHP_AUTH_USER']=$_server['PHP_AUTH_USER'];$headers['PHP_AUTH_PW']=$_server['PHP_AUTH_PW']?? '';}else{$authorizationHeader=null;if(isset($_server['HTTP_AUTHORIZATION'])){$authorizationHeader=$_server['HTTP_AUTHORIZATION'];}elseif(isset($_server['REDIRECT_HTTP_AUTHORIZATION'])){$authorizationHeader=$_server['REDIRECT_HTTP_AUTHORIZATION'];}if(null!==$authorizationHeader){if(0===\stripos($authorizationHeader,'basic ')){$exploded=\explode(':',\base64_decode(\substr($authorizationHeader,6)),2);if(2==\count($exploded)){[$headers['PHP_AUTH_USER'],$headers['PHP_AUTH_PW']]=$exploded;}}elseif(empty($_server['PHP_AUTH_DIGEST'])&&0===\stripos($authorizationHeader,'digest ')){$headers['PHP_AUTH_DIGEST']=$authorizationHeader;$_server['PHP_AUTH_DIGEST']=$authorizationHeader;}elseif(0===\stripos($authorizationHeader,'bearer ')){$headers['AUTHORIZATION']=$authorizationHeader;}}}if(isset($headers['AUTHORIZATION'])){return $headers;}if(isset($headers['PHP_AUTH_USER'])){$headers['AUTHORIZATION']='Basic '.\base64_encode($headers['PHP_AUTH_USER'].':'.($headers['PHP_AUTH_PW']?? ''));}elseif(isset($headers['PHP_AUTH_DIGEST'])){$headers['AUTHORIZATION']=$headers['PHP_AUTH_DIGEST'];}return $headers;}